export const RESOLVING_CONFLICT_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu konflik",q:"'Konflik' dalam tim atau pertemanan biasanya terjadi ketika...",options:["Ada kebutuhan, pendapat, atau harapan yang berbeda & terasa berbenturan","Berarti ada pihak yang berniat jahat dan sengaja merusak suasana","Tidak terjadi di tim yang baik karena anggotanya sudah sepakat"],answer:0,explain:"Konflik adalah perbedaan yang terasa berbenturan. Ia wajar & bisa diselesaikan dengan baik atau buruk.",hint:"Perbedaan yang berbenturan, atau tanda ada yang jahat?"},
{n:2,type:"mcq",micro:"Konflik itu wajar",q:"Konflik sesekali dalam kelompok yang bekerja bersama...",options:["Harus dihindari dengan diam dan pura-pura tidak ada masalah","Wajar & normal; yang menentukan adalah bagaimana ia ditangani","Menjadi tanda tim gagal sehingga kelompok sebaiknya dibubarkan"],answer:1,explain:"Tim yang tidak pernah berkonflik sering hanya menyembunyikan masalah. Konflik yang ditangani baik menguatkan tim.",hint:"Wajar & tergantung penanganan, atau tanda gagal?"},
{n:3,type:"mcq",micro:"Tenang dulu",q:"Saat konflik memanas & emosi tinggi, langkah pertama yang membantu:",options:["Terus berdebat selagi suasana panas supaya masalah cepat selesai, sebelum ada waktu mencari alasan pembelaan","Meledak marah sekeras mungkin agar mereka tahu betapa kesalnya kamu dan segera meminta maaf","Beri jeda: 'Ayo kita tenang dulu, lanjut bicara nanti setelah adem' — daripada bicara saat marah"],answer:2,explain:"Kata-kata yang keluar saat marah sulit ditarik. Jeda mencegah kerusakan yang sulit diperbaiki.",hint:"Jeda untuk tenang, atau terus berdebat panas?"},
{n:4,type:"mcq",micro:"Dengar kedua sisi",q:"Untuk menyelesaikan konflik antara dua orang, penting...",options:["Mendengar cerita kedua pihak secara penuh & adil, bukan hanya satu sisi","Percaya pada orang yang bicara lebih dulu karena biasanya paling dirugikan","Putuskan siapa yang salah dari kesan pertama supaya konflik cepat selesai"],answer:0,explain:"Satu sisi cerita hampir selalu tidak lengkap. Mendengar keduanya sering mengungkap salah paham.",hint:"Dengar kedua sisi, atau percaya yang duluan?"},
{n:5,type:"mcq",micro:"Fokus pada masalah, bukan orang",q:"Menyelesaikan konflik lebih mudah bila fokusnya...",options:["Pada siapa yang paling menderita akibat masalah, lalu orang itu diberi hak menentukan hukuman bagi pihak lain","Pada masalah yang perlu dipecahkan ('bagaimana kita bagi tugas dengan adil?'), bukan pada menyalahkan orang","Pada mencari siapa yang paling bersalah, lalu memastikan ia mengakui kesalahannya di depan anggota tim"],answer:1,explain:"'Kita vs masalah' jauh lebih produktif daripada 'aku vs kamu'.",hint:"Pada masalah yang dipecahkan, atau pada siapa yang salah?"},
{n:6,type:"mcq",micro:"Pernyataan 'aku'",q:"Menyampaikan keluhan dalam konflik yang tidak memicu pertahanan:",options:["'Kamu itu orangnya semaunya sendiri dan tidak peduli perasaan orang lain' — menyerang karakter","Diam dan memusuhi dia diam-diam, lalu membicarakannya dengan teman lain tanpa bilang padanya","'Aku merasa kesal waktu bagianku dikerjakan ulang tanpa bilang' — pakai 'aku merasa' + situasi spesifik"],answer:2,explain:"'Kamu selalu...' memicu bantahan. 'Aku merasa... waktu...' membuka percakapan.",hint:"'Aku merasa' + situasi, atau menyerang karakter?"},
{n:7,type:"mcq",micro:"Mengakui bagianmu",q:"Dalam banyak konflik, sikap yang mempercepat penyelesaian:",options:["Mengakui bagian yang jadi andilmu: 'Aku juga salah karena nggak jelasin dari awal'","Bersikeras bahwa kamu 100% benar dan lawanmu 100% salah, supaya ia menyerah sendiri","Menyalahkan keadaan sepenuhnya, misalnya 'gara-gara waktunya mepet'"],answer:0,explain:"Konflik jarang murni salah satu pihak. Mengakui andilmu membuat pihak lain lebih mau mengakui andilnya.",hint:"Akui andilmu, atau ngotot 100% benar?"},
{n:8,type:"mcq",micro:"Nada saat menyelesaikan konflik",q:"Nada suara yang membantu meredakan konflik:",options:["Sinis dan menyindir halus sambil tersenyum, supaya lawan sadar sendiri","Tenang & volume rendah — sering membuat lawan bicara ikut menurunkan nada","Meninggi menandingi lawan sampai ia mengalah dan berhenti bicara"],answer:1,explain:"Nada menular. Menurunkan volume & memperlambat bicara adalah 'rem' pertama sebuah pertengkaran.",hint:"Tenang & rendah, atau meninggi / sinis?"},
{n:9,type:"order",micro:"Menyelesaikan konflik kecil",q:"Urutkan langkah menyelesaikan konflik kecil dengan teman tim.",items:["Tenangkan diri; ajak bicara berdua di waktu & tempat yang tenang","Sampaikan dengan pernyataan 'aku': situasi + perasaan","Dengarkan sudut pandangnya tanpa memotong","Cari solusi bersama & sepakati langkah ke depan"],answer:[0,1,2,3],explain:"Tenang & ajak bicara → sampaikan 'aku' → dengarkan → cari solusi bersama. Bukan menyindir atau mendiamkan.",hint:"Apa yang dilakukan sebelum menyampaikan perasaan?"},
{n:10,type:"mcq",micro:"Menghindari vs menyelesaikan",q:"Terus-menerus menghindari konflik (pura-pura tidak ada masalah) biasanya membuat...",options:["Masalah hilang dengan sendirinya setelah beberapa hari berlalu tanpa dibicarakan","Tim jadi lebih kuat karena anggotanya belajar menahan diri dan tidak mengeluh","Masalah menumpuk & meledak lebih besar nanti, atau hubungan jadi dingin & tidak jujur"],answer:2,explain:"Menghindar meredakan ketegangan sekarang tapi menyimpan bom waktu. Konflik kecil lebih mudah diselesaikan daripada yang menumpuk.",hint:"Menumpuk & meledak, atau hilang sendiri?"},
{n:11,type:"tf",micro:"Konflik bisa menguatkan",q:"Benar atau Salah: Konflik yang diselesaikan dengan baik bisa membuat tim atau pertemanan lebih kuat, karena masalah dibicarakan & saling pengertian bertambah.",answer:true,explain:"Hubungan terkuat bukan yang tanpa konflik, melainkan yang bisa melewati konflik dengan jujur & hormat.",hint:"Bisa menguatkan bila diselesaikan baik, atau selalu merusak?"},
{n:12,type:"tf",micro:"Diam selalu jalan terbaik?",q:"Benar atau Salah: Cara terbaik menghadapi konflik dalam tim selalu adalah diam & mengalah, agar tidak ada keributan.",answer:false,explain:"Sebaliknya, mengalah terus menyimpan kekesalan & membiarkan masalah tak terselesaikan. Kadang konflik perlu dibicarakan langsung dengan tenang & hormat.",hint:"Selalu diam & mengalah, atau bicarakan dengan tenang?"},
{n:13,type:"mcq",micro:"Menyelesaikan konflik = win-win",q:"Solusi konflik yang paling bertahan lama biasanya...",options:["Yang kebutuhan inti kedua pihak sebagian besar terpenuhi (menang-menang), bukan yang satu menang total & satu kalah total","Yang satu pihak menang mutlak dan pihak lain kalah, karena keputusan tegas lebih mudah diingat dan dipatuhi anggota","Yang tidak menyelesaikan masalah tetapi membuat suasana tampak damai, sehingga tak ada pihak yang perlu mengubah kebiasaan"],answer:0,explain:"Solusi di mana satu pihak kalah total sering menyimpan dendam & muncul lagi. Solusi yang mengakomodasi keduanya lebih kokoh.",hint:"Menang-menang, atau satu menang total?"},
{n:14,type:"mcq",micro:"Waktu & tempat",q:"Membicarakan konflik sebaiknya dilakukan...",options:["Lewat pesan sindiran di grup chat tim, supaya yang bersangkutan sadar tanpa dibicarakan langsung","Berdua di tempat & waktu tenang, bukan di depan banyak orang atau saat salah satu sedang terburu-buru","Di depan seluruh tim agar semua ikut menilai siapa yang benar, sehingga keputusannya terasa adil"],answer:1,explain:"Konflik yang dibahas di depan umum menambah rasa malu & pertahanan. Empat mata & tenang lebih aman.",hint:"Berdua & tenang, atau di depan umum / sindiran?"},
{n:15,type:"mcq",micro:"Mengakui perasaan lawan",q:"Kalimat yang membantu meredakan konflik:",options:["'Kamu lebay banget, begitu saja kok marah. Masalah sekecil itu nggak perlu dibesar-besarkan.'","'Itu masalahmu, bukan masalahku. Aku nggak ada urusan dengan perasaanmu & nggak mau ikut memikirkannya, ya.'","'Aku ngerti kenapa kamu kesal soal itu' — mengakui perasaannya (bukan berarti setuju semua)"],answer:2,explain:"Orang yang merasa perasaannya diakui lebih mudah menurunkan pertahanan & mendengar.",hint:"Akui perasaannya, atau meremehkan / menolak?"},
{n:16,type:"mcq",micro:"Konflik soal fakta vs perasaan",q:"Kadang konflik terjadi karena salah paham fakta ('kukira kamu yang kerjakan'). Cara menyelesaikannya:",options:["Cek fakta bersama & luruskan; sering konflik langsung mereda begitu salah pahamnya terungkap","Terus bertengkar tanpa mengecek fakta, karena makin keras berdebat makin jelas siapa yang benar","Berasumsi lawan bicaramu sengaja berbohong untuk menghindari tugas, lalu menuntutnya mengaku di depan tim"],answer:0,explain:"Banyak 'pertengkaran' sebenarnya salah paham yang bisa dibersihkan dengan mengecek fakta bersama.",hint:"Cek fakta & luruskan, atau bertengkar tanpa cek?"},
{n:17,type:"mcq",micro:"Menahan balas menyerang",q:"Saat lawan bicara mengatakan sesuatu yang menyakiti di tengah konflik, respons yang tidak memperkeruh:",options:["Diam menahan semuanya sampai tak tahan lagi, lalu meledak di waktu lain dengan kekesalan yang menumpuk","'Bagian tadi terasa menyakitkan buatku. Ayo kita fokus ke masalahnya.' — sebut perasaanmu, kembalikan ke isi","Balas dengan kata-kata yang lebih menyakitkan supaya ia merasakan rasanya dan tidak berani mengulangi"],answer:1,explain:"Menyuarakan perasaan dengan tenang & mengarahkan kembali ke masalah menjaga konflik tidak jadi perang.",hint:"Sebut perasaan + kembali ke isi, atau balas menyakiti / pendam?"},
{n:18,type:"mcq",micro:"Kapan minta bantuan orang lain",q:"Kapan konflik sebaiknya melibatkan penengah (guru, pembimbing)?",options:["Pada semua konflik sekecil apa saja, karena kedua pihak tak bisa bicara baik-baik tanpa orang dewasa yang mengawasi","Pada konflik besar saja; konflik biasa harus diselesaikan sendiri oleh kedua pihak walau ada yang takut","Ketika kedua pihak sudah mencoba bicara tapi buntu, atau ketika ada yang merasa tidak aman/terintimidasi"],answer:2,explain:"Coba selesaikan sendiri dulu; libatkan penengah bila buntu atau ada ketidakamanan. Bukan langsung, bukan tidak pernah.",hint:"Saat buntu / tidak aman, atau selalu / tidak pernah?"},
{n:19,type:"mcq",micro:"Setelah konflik selesai",q:"Setelah menyelesaikan konflik, sikap yang menjaga hubungan:",options:["Anggap masalah selesai; tidak mengungkit-ungkitnya lagi & tidak menyimpan dendam","Terus mengingatkan lawan tentang kesalahannya dulu supaya ia tidak mengulanginya","Bersikap dingin dan menjaga jarak walau sudah 'damai', supaya ia menyadari besar kesalahannya"],answer:0,explain:"Konflik yang diselesaikan tapi terus diungkit tidak benar-benar selesai. Melepaskannya adalah bagian dari penyelesaian.",hint:"Anggap selesai & lepaskan, atau terus mengungkit / dingin?"},
{n:20,type:"open",micro:"Menyelesaikan konflik pribadi",q:"Kamu & temanmu Tita sekelompok. Tita mengubah bagian pekerjaanmu tanpa bertanya karena menurutnya 'kurang bagus'. Kamu kesal & merasa tidak dihargai. Tulis bagaimana kamu akan menyelesaikan konflik ini dengan Tita, lalu jelaskan pilihanmu.",explain:"Jawaban baik: tenang dulu, ajak bicara berdua di tempat tenang, pakai pernyataan 'aku' (situasi + perasaan), dengarkan sisi Tita tanpa memotong, akui andil sendiri, cari solusi/aturan bersama untuk ke depan, lalu lepaskan — dengan penjelasan alasan tiap langkah (bukan menyindir/mendiamkan, mencegah defensif, 'kita vs masalah', mencegah terulang).",hint:"Tenang → bicara berdua → 'aku merasa' → dengar sisinya → akui andilmu → solusi/aturan bersama → lepaskan. Jelaskan kenapa tiap langkah.",sample:"Langkah: (1) Aku tenangkan diri dulu, tidak menyahut kasar saat masih kesal. (2) Aku ajak Tita bicara berdua di waktu tenang, bukan di depan anggota lain: 'Tita, boleh ngobrol bentar soal tugas kita?' (3) Aku sampaikan dengan pernyataan 'aku': 'Waktu bagianku kamu ubah tanpa bilang dulu, aku merasa kesal dan kayak nggak dihargai. Mungkin kamu bermaksud baik, tapi aku pengin diajak bicara dulu.' (4) Aku dengarkan sisi Tita tanpa memotong — mungkin ia benar-benar melihat masalah dan panik karena tenggat dekat. (5) Aku akui bila ada andilku: mungkin aku memang tidak menjelaskan rencanaku dengan jelas dari awal. (6) Kami cari solusi bersama untuk ke depan: kalau ada yang mau mengubah bagian orang lain, bahas dulu berdua; kalau memang bagianku perlu diperbaiki, Tita kasih tahu apa yang kurang dan aku yang perbaiki. (7) Setelah sepakat, aku anggap masalah selesai dan tidak mengungkitnya lagi. Penjelasan: aku memilih bicara langsung dan tenang (bukan menyindir atau mendiamkan) supaya masalahnya benar-benar diselesaikan; aku pakai 'aku merasa' supaya Tita tidak langsung defensif; aku dengar sisinya dan akui andilku supaya ini terasa 'kita vs masalah', bukan 'aku vs Tita'; dan aku fokus pada aturan ke depan supaya konflik yang sama tidak terulang."},
{n:21,type:"classify",micro:"Menangani konflik: sehat vs merusak",q:"Kelompokkan tiap respons konflik ke 'Sehat' atau 'Merusak'.",items:["Bicara berdua dengan tenang & pernyataan 'aku'","Menyindir lewat status/story","Mendengar sisi lawan & mengakui andil sendiri","Menyebarkan cerita satu sisi ke teman lain untuk cari dukungan"],groups:["Sehat","Merusak"],answer:{"Sehat":["Bicara berdua dengan tenang & pernyataan 'aku'","Mendengar sisi lawan & mengakui andil sendiri"],"Merusak":["Menyindir lewat status/story","Menyebarkan cerita satu sisi ke teman lain untuk cari dukungan"]},explain:"Sehat: langsung, tenang, dua arah. Merusak: tidak langsung (sindiran), atau membangun kubu lewat gosip.",hint:"Langsung & dua arah, atau menyindir / membentuk kubu?"},
{n:22,type:"mcq",micro:"Gaya menghadapi konflik",q:"Lima gaya umum menghadapi konflik: menghindar, mengalah, memaksa/bersaing, kompromi, & kolaborasi. Yang paling sering menghasilkan solusi terbaik untuk masalah penting:",options:["Menghindar — pura-pura tidak ada masalah dan mengalihkan pembicaraan","Kolaborasi — mencari solusi yang memenuhi kebutuhan inti kedua pihak","Memaksa — menang dengan menekan lawan sampai menyerah dan berhenti membantah"],answer:1,explain:"Kolaborasi butuh waktu & usaha lebih, tapi menghasilkan solusi yang bertahan & menjaga hubungan. Kompromi cepat cocok untuk hal kecil.",hint:"Kolaborasi (kebutuhan inti keduanya), atau memaksa / menghindar?"},
{n:23,type:"mcq",micro:"Kebutuhan di balik posisi",q:"Dalam konflik, 'posisi' adalah apa yang orang minta; 'kebutuhan' adalah alasan di baliknya. Menggali kebutuhan berguna karena...",options:["Posisi sama dengan kebutuhan, jadi tak perlu menggali alasan di balik permintaan","Kebutuhan tidak penting; yang terpenting siapa yang paling keras bertahan pada posisinya","Sering ada solusi yang memenuhi kebutuhan kedua pihak meski posisi awalnya berbenturan"],answer:2,explain:"Contoh klasik: dua orang berebut jeruk. Satu butuh kulitnya (untuk kue), satu butuh isinya. Menggali kebutuhan mengungkap solusi.",hint:"Menemukan solusi untuk kebutuhan keduanya, atau posisi = kebutuhan?"},
{n:24,type:"mcq",micro:"Menghindar yang sah vs merusak",q:"Kapan menghindari/menunda konflik itu SAH?",options:["Untuk masalah yang benar-benar kecil & tidak mengganggu, atau menunda sementara sampai semua tenang & siap bicara","Untuk semua konflik, karena menghindar lebih aman daripada membicarakannya dan masalah selesai dengan sendirinya","Hindari menunda; semua konflik, sekecil apa saja, harus dihadapi saat itu juga walau pihak-pihak sedang marah dan lelah"],answer:0,explain:"Membiarkan hal sepele lewat, atau menunda saat emosi tinggi, itu bijak. Menghindari masalah penting selamanya, tidak.",hint:"Untuk hal kecil / menunda sementara, atau selalu / tidak pernah?"},
{n:25,type:"mcq",micro:"Membentuk kubu (triangulasi)",q:"Menceritakan konflikmu dengan seseorang ke banyak teman lain untuk 'cari dukungan' biasanya...",options:["Netral dan tak berpengaruh, karena teman yang mendengar hanya mendengarkan lalu melupakannya","Memperburuk: masalah menyebar, versi satu sisi jadi 'kebenaran', & lawan merasa dikeroyok","Membantu menyelesaikan konflik cepat, karena makin banyak pembela, lawan makin cepat sadar"],answer:1,explain:"Konflik diselesaikan antara pihak yang terlibat, bukan dengan membangun pasukan. Curhat ke SATU orang tepercaya untuk perspektif berbeda dari 'mencari sekutu'.",hint:"Memperburuk & membentuk kubu, atau membantu?"},
{n:26,type:"mcq",micro:"Mengulang untuk memahami",q:"Di tengah konflik, meminta 'coba aku ulang ya, maksud kamu...' berguna karena...",options:["Membuang waktu karena keluhannya sudah jelas sejak kalimat pertama, lebih baik langsung menjawab","Membuat lawan makin marah karena merasa diulang-ulang dan dipancing bicara panjang lebar","Memastikan kamu benar-benar paham keluhannya (banyak konflik adalah salah paham) & lawan merasa didengar"],answer:2,explain:"Memantulkan keluhan lawan sering langsung menurunkan tensi karena ia merasa 'akhirnya ada yang dengar'.",hint:"Memastikan paham + lawan merasa didengar, atau buang waktu?"},
{n:27,type:"tf",micro:"Konflik yang dipendam",q:"Benar atau Salah: Kekesalan yang dipendam demi 'menjaga kedamaian' biasanya hilang dengan sendirinya seiring waktu, tanpa efek buruk.",answer:false,explain:"Sebaliknya, kekesalan yang dipendam cenderung menumpuk & bisa meledak lebih besar nanti, atau membuat hubungan terasa dingin & tidak jujur. Membicarakan masalah kecil lebih awal jauh lebih mudah.",hint:"Menumpuk & meledak, atau hilang sendiri?"},
{n:28,type:"tf",micro:"Menyelesaikan konflik = harus ada yang mengaku salah?",q:"Benar atau Salah: Sebuah konflik hanya bisa selesai bila salah satu pihak mengakui bahwa dialah yang sepenuhnya salah.",answer:false,explain:"Sebaliknya, banyak konflik selesai tanpa 'pemenang' — lewat saling memahami, mengakui andil masing-masing, & menyepakati langkah ke depan. Menuntut pengakuan salah total sering malah membuat buntu.",hint:"Harus ada yang mengaku salah total, atau bisa saling memahami + langkah ke depan?"},
{n:29,type:"mcq",micro:"Emosi dalam konflik",q:"Peran emosi (marah, sedih, takut) dalam konflik:",options:["Emosi adalah sinyal bahwa sesuatu penting bagimu; akui & sampaikan dengan tenang, jangan biarkan ia mengendalikan kata-katamu","Emosi tidak boleh ada dalam diskusi, jadi orang yang marah atau sedih sebaiknya diam sampai perasaannya hilang, lalu baru bicara","Emosi harus diluapkan sebesar-besarnya agar kamu terlihat jujur, tanpa peduli kata-katamu melukai perasaan lawan bicaramu"],answer:0,explain:"Menekan emosi total tidak realistis; meluapkannya merusak. Yang sehat: mengakui emosi & mengaturnya.",hint:"Akui & atur, atau tekan total / luapkan?"},
{n:30,type:"order",micro:"Menengahi konflik dua teman",q:"Urutkan langkah menengahi konflik antara dua anggota tim.",items:["Ajak keduanya duduk bersama di waktu tenang; sepakati aturan: bicara bergantian, tidak menghina","Minta tiap orang menceritakan versinya + perasaannya, yang lain menyimak tanpa memotong","Minta tiap orang mengulang inti keluhan lawannya sampai lawan berkata 'ya, itu maksudku'","Bantu mereka menemukan kebutuhan bersama & menyepakati langkah/aturan ke depan"],answer:[0,1,2,3],explain:"Aturan aman → cerita bergantian → saling memantulkan → temukan kebutuhan bersama & sepakati. Penengah memfasilitasi, tidak menghakimi.",hint:"Apa yang disepakati sebelum cerita dimulai?"},
{n:31,type:"mcq",micro:"Konflik & rasa aman",q:"Agar konflik bisa diselesaikan dengan jujur, kedua pihak perlu merasa...",options:["Bahwa mereka harus menang atau kalah total, sehingga masing-masing bertahan pada posisinya","Aman — bahwa menyampaikan keluhan tidak akan membuat mereka dihina, dimusuhi, atau dihukum","Takut kepada pihak yang lebih kuat, agar cepat mengalah dan konflik segera selesai"],answer:1,explain:"Konflik yang diselesaikan dalam suasana takut hanya menghasilkan 'perdamaian' di permukaan. Rasa aman memungkinkan kejujuran.",hint:"Aman untuk jujur, atau takut / menang-kalah?"},
{n:32,type:"tf",micro:"Konflik ide vs konflik pribadi",q:"Benar atau Salah: Konflik yang sudah berubah menjadi serangan pribadi & permusuhan justru lebih mudah diselesaikan daripada konflik yang masih soal ide.",answer:false,explain:"Sebaliknya, begitu konflik jadi 'aku benci kamu', pokok masalah asli sering terlupakan & yang tersisa hanya luka. Konflik soal ide lebih mudah diselesaikan, jadi menjaga konflik tetap tentang isi itu penting.",hint:"Konflik ide lebih mudah, atau konflik pribadi lebih mudah?"},
{n:33,type:"mcq",micro:"Meminta maaf yang tulus",q:"Permintaan maaf yang membantu menyelesaikan konflik:",options:["'Maaf ya kalau kamu merasa tersinggung dengan ucapanku.' (seolah masalahnya ada pada perasaan lawan)","'Maaf, tapi kamu juga salah karena tidak mengingatkan aku.' (permintaan maaf yang diikuti menyalahkan lawan)","'Maaf ya, aku salah karena mengubah bagianmu tanpa bilang. Itu pasti bikin kamu kesal. Lain kali aku akan tanya dulu.'"],answer:2,explain:"Maaf tulus: sebut kesalahan spesifik + akui dampak + niat perbaikan. Bukan 'maaf kalau...' atau maaf berbumbu tuduhan.",hint:"Sebut kesalahan + dampak + niat perbaikan, atau 'maaf kalau' / maaf + tuduhan?"},
{n:34,type:"mcq",micro:"Konflik berulang",q:"Sebuah konflik yang sama terus muncul di tim. Ini tanda...",options:["Akar masalahnya belum diselesaikan, hanya gejalanya; perlu membahas penyebab yang lebih dalam & membuat aturan/kesepakatan","Tim ini memang ditakdirkan bermasalah sejak awal, jadi konflik berulang tidak bisa dicegah dan perlu diterima","Salah satu orang harus dikeluarkan supaya konflik berhenti, karena konflik berulang biasanya disebabkan satu orang bermasalah"],answer:0,explain:"Konflik yang berulang berarti solusi sebelumnya hanya menambal permukaan. Gali akarnya & buat kesepakatan yang mengatasinya.",hint:"Akar belum diselesaikan, atau tim ditakdirkan buruk?"},
{n:35,type:"mcq",micro:"Konflik & pihak ketiga netral",q:"Peran penengah/mediator yang baik:",options:["Menghukum pihak yang menurutnya salah, lalu memastikan pihak itu minta maaf dengan disaksikan anggota lain","Membantu kedua pihak saling mendengar & menemukan solusi sendiri — bukan memutuskan siapa yang menang","Memihak orang yang paling meyakinkan saat bercerita, sebab kemampuan menjelaskan tanda yang bisa dipercaya"],answer:1,explain:"Mediator memfasilitasi, tidak menghakimi. Solusi yang ditemukan para pihak sendiri lebih bertahan.",hint:"Memfasilitasi + para pihak temukan solusi, atau memihak / menghukum?"},
{n:36,type:"mcq",micro:"Bahasa tubuh saat menyelesaikan konflik",q:"Bahasa tubuh yang membantu meredakan konflik:",options:["Menunjuk-nunjuk dengan jari, mendekat sampai terasa mengancam, dan menatap tajam supaya kamu terlihat serius","Membelakangi lawan bicara dan menyilangkan tangan erat di dada, supaya jelas kamu tak mau mendengar alasannya","Tubuh terbuka, jaga jarak nyaman, kontak mata yang tidak menantang, gerakan tenang tanpa tiba-tiba"],answer:2,explain:"Tubuh yang tenang & terbuka menyampaikan 'aku tidak menyerangmu', membantu lawan menurunkan pertahanan.",hint:"Terbuka & tenang, atau mengancam / menutup?"},
{n:37,type:"tf",micro:"Menyelesaikan konflik bisa dilatih",q:"Benar atau Salah: Menyelesaikan konflik dengan sehat — tenang dulu, dengar dua sisi, pakai pernyataan 'aku', gali kebutuhan, cari solusi bersama — adalah keterampilan yang bisa dipelajari & diasah.",answer:true,explain:"Tidak ada yang lahir jago menyelesaikan konflik. Latihan & kesadaran membuat kamu makin baik.",hint:"Bisa dilatih, atau bawaan?"},
{n:38,type:"mcq",micro:"Konflik & tujuan bersama",q:"Mengingatkan diri & lawan tentang tujuan bersama di tengah konflik ('kita sama-sama mau proyek ini berhasil') berguna karena...",options:["Menggeser fokus dari 'aku vs kamu' ke 'kita vs masalah', membuat kerja sama lebih mungkin","Menghindari masalah supaya suasana tidak panas dan pihak-pihak bisa menjauh sementara","Membuat lawan merasa bersalah sehingga ia mengalah dan menerima usulanmu dengan cepat"],answer:0,explain:"Menemukan kembali tujuan bersama sering mencairkan konflik karena kedua pihak ingat mereka satu tim.",hint:"Geser ke 'kita vs masalah', atau menghindari / menyalahkan?"},
{n:39,type:"mcq",micro:"Kapan solusi belum ketemu",q:"Kalau setelah berdiskusi belum ada solusi & waktu habis, sikap yang membangun:",options:["Salah satu pihak memaksakan kehendaknya sampai pihak lain menyerah, supaya masalahnya selesai hari itu juga & tidak perlu dibahas lagi lain waktu","Sepakati untuk melanjutkan pembahasan di waktu tertentu, catat poin yang sudah disepakati, & sementara ambil keputusan yang wajar bila mendesak","Berhenti bicara & saling mendiamkan sampai ada yang mau mengalah lebih dulu, karena waktu pembahasan sudah habis dan tidak ada gunanya lanjut"],answer:1,explain:"Konflik tidak selalu selesai dalam satu percakapan. Menjadwalkan lanjutan + keputusan sementara lebih baik daripada buntu atau paksaan.",hint:"Jadwalkan lanjutan + keputusan sementara, atau mendiamkan / memaksa?"},
{n:40,type:"open",micro:"Menggali kebutuhan di balik posisi",q:"Dua anggota tim, Rara & Sam, bertengkar: Rara ingin proyek dikerjakan sepenuhnya di sekolah setelah jam pelajaran; Sam ingin dikerjakan di rumah masing-masing lalu digabung. Masing-masing bersikeras. Jelaskan bagaimana menggali KEBUTUHAN di balik posisi mereka bisa membantu menemukan solusi, dan usulkan satu solusi yang mungkin.",explain:"Jawaban baik: membedakan posisi (yang diminta) dari kebutuhan (alasan di baliknya), menebak kebutuhan masuk akal tiap pihak (Rara: takut menanggung sendiri / tak ada fasilitas di rumah; Sam: sibuk / lebih fokus sendiri), menunjukkan keduanya sebenarnya sejalan (ingin proyek berhasil tanpa dirugikan), dan mengusulkan solusi yang memenuhi kebutuhan inti keduanya (sesi bersama singkat + bagian individual + tenggat & cek kemajuan).",hint:"Tanyakan alasan di balik tiap posisi → temukan kebutuhan inti (kepastian kontribusi, fasilitas, waktu, fokus) → usulkan solusi yang penuhi kebutuhan keduanya (sesi bersama singkat + kerja individual + cek kemajuan).",sample:"Posisi Rara: 'kerjakan di sekolah'. Posisi Sam: 'kerjakan di rumah lalu gabung'. Untuk menyelesaikan, tanyakan alasan (kebutuhan) di balik masing-masing. Mungkin kebutuhan Rara: ia merasa kalau dikerjakan terpisah, ada yang tidak akan mengerjakan bagiannya dan ia takut menanggung sendiri; ia juga mungkin tidak punya internet/tempat tenang di rumah. Kebutuhan Sam: ia sibuk kegiatan lain setelah sekolah sehingga sulit tinggal lama, dan ia merasa lebih fokus mengerjakan sendiri. Begitu kebutuhan terungkap, terlihat bahwa keduanya sebenarnya ingin proyek selesai dengan baik dan tidak dirugikan — bukan benar-benar berlawanan. Solusi yang mungkin: bagian yang butuh kerja bersama dan koordinasi dikerjakan di sekolah dalam sesi singkat 2-3 kali (misalnya 45 menit, bukan berjam-jam) supaya Sam masih sempat; bagian individual dikerjakan masing-masing di rumah atau di perpustakaan sekolah bagi yang tidak punya fasilitas; ada tenggat internal per bagian dan cek kemajuan supaya kekhawatiran Rara soal ada yang tidak mengerjakan bagiannya teratasi. Dengan begitu kebutuhan Rara (kepastian semua berkontribusi + tempat kerja) dan Sam (tidak terkuras waktunya + bisa fokus sendiri) sama-sama sebagian besar terpenuhi."},
{n:41,type:"mcq",micro:"Skenario: konflik lewat chat",q:"Kamu & teman tim bertengkar lewat chat & suasananya makin panas. Sikap yang bijak:",options:["Terus balas-balasan di chat dengan nada makin tajam sampai salah satu menyerah dan berhenti membalas pesan itu","Blokir dia dari grup dan akun supaya tidak ada lagi pesan yang membuatmu kesal, lalu lanjut bekerja sendiri","'Kayaknya lewat chat malah tambah salah paham. Bisa kita ngobrol langsung/telepon nanti?' — pindahkan ke media yang lebih baik"],answer:2,explain:"Teks kehilangan nada & mudah salah tafsir. Konflik emosional lebih baik dibahas langsung.",hint:"Pindahkan ke bicara langsung, atau lanjut di chat / blokir?"},
{n:42,type:"mcq",micro:"Skenario: dituduh padahal tidak bersalah",q:"Anggota tim menuduhmu tidak mengerjakan bagianmu, padahal kamu sudah. Sikap:",options:["Tetap tenang, tunjukkan bukti bagianmu, & tanyakan apa yang membuatnya berpikir begitu — mungkin ia belum melihat/menerima hasilmu","Balas menuduh dia lebih keras bahwa ia sendiri yang tidak mengerjakan bagiannya, supaya ia berhenti dan tidak berani menuduh orang sembarangan lagi","Diam saja & membiarkan tuduhan itu beredar di tim, karena membela diri hanya akan membuat suasana makin panas & kamu terlihat tidak sopan"],answer:0,explain:"Menanggapi tuduhan dengan bukti + rasa ingin tahu ('kok bisa gitu?') lebih menyelesaikan daripada membalas atau diam.",hint:"Tenang + tunjukkan bukti + tanya, atau balas menuduh / diam?"},
{n:43,type:"mcq",micro:"Skenario: konflik karena beban tidak adil",q:"Kamu kesal karena mengerjakan jauh lebih banyak daripada anggota lain. Cara menyampaikan:",options:["Memendam semuanya dan terus mengerjakan semua bagian sambil marah dalam hati, tanpa menyampaikan kepada tim, sampai tak sanggup lagi","'Aku merasa beban kita nggak seimbang — aku pegang 3 bagian, yang lain 1. Bisa kita bagi ulang?' — fakta + perasaan + usul solusi","'Kalian pemalas, aku kerja sendirian terus tiap hari!' — dikatakan keras di depan tim supaya mereka malu dan berubah"],answer:1,explain:"Menyampaikan ketidakadilan dengan data + usul solusi lebih produktif daripada menuduh atau memendam.",hint:"Fakta + perasaan + usul, atau menuduh / pendam?"},
{n:44,type:"mcq",micro:"Skenario: konflik memuncak di rapat",q:"Di rapat, dua anggota mulai saling meninggikan suara. Sebagai anggota lain:",options:["Ikut memihak salah satu dan menambah panas dengan komentar yang mendukungnya, supaya pihak itu merasa menang","Diam sambil merekam kejadian itu diam-diam sebagai bukti, lalu menunjukkannya ke guru untuk menyalahkan salah satu","'Ayo kita berhenti sebentar. Ini penting, tapi kita perlu bahas dengan tenang. Satu-satu ya.' — tetapkan jeda & aturan"],answer:2,explain:"Siapa pun bisa membantu menenangkan konflik dengan menetapkan jeda & aturan bicara, tanpa memihak.",hint:"Jeda + aturan bicara, atau memihak / merekam?"},
{n:45,type:"order",micro:"Percakapan menyelesaikan konflik",q:"Urutkan alur percakapan menyelesaikan konflik berdua.",items:["Buka dengan tujuan positif: 'Aku mau kita selesaikan ini karena aku hargai kerja sama kita'","Sampaikan keluhanmu dengan 'aku merasa... waktu...' — spesifik, tanpa menyerang","Dengarkan sisinya penuh; pantulkan: 'Jadi kamu merasa... karena...'","Cari solusi bersama & sepakati langkah ke depan, lalu tutup dengan baik"],answer:[0,1,2,3],explain:"Tujuan positif → keluhan 'aku' → dengar & pantulkan → solusi bersama & tutup baik. Membuka dengan niat baik menurunkan pertahanan.",hint:"Apa yang dibuka di awal sebelum menyampaikan keluhan?"},
{n:46,type:"mcq",micro:"Skenario: lawan tidak mau bicara",q:"Kamu ingin menyelesaikan konflik tapi lawan menolak bicara & terus menghindar. Sikap:",options:["Beri ruang sebentar, sampaikan sekali dengan tenang bahwa kamu ingin menyelesaikannya & siap kapan pun; bila menyangkut tugas & tetap buntu, libatkan penengah","Memaksanya bicara sekarang juga dengan menahan ia di tempat sampai mau menjelaskan, karena menunda hanya akan membuat masalahnya makin besar","Membalas menghindar dan memusuhinya juga, supaya ia merasakan sendiri bagaimana rasanya diabaikan, lalu mau datang untuk menyelesaikannya duluan"],answer:0,explain:"Kamu tidak bisa memaksa orang siap. Menyatakan kesediaan + memberi ruang, lalu melibatkan penengah bila perlu.",hint:"Nyatakan kesediaan + beri ruang + penengah bila perlu, atau memaksa / balas menghindar?"},
{n:47,type:"mcq",micro:"Skenario: konflik & tenggat mepet",q:"Ada konflik serius tapi tenggat proyek besok. Sikap yang praktis:",options:["Selesaikan konflik dulu sampai tuntas hari ini juga, walaupun proyek jadi terbengkalai dan gagal dikumpulkan, karena hubungan lebih penting dari tugas","Sepakati 'gencatan senjata': selesaikan proyek dulu secara profesional, jadwalkan membahas konflik setelahnya dengan tenang","Biarkan konflik terus berjalan tanpa dibatasi & menghancurkan proyek, karena tenggat tidak ada hubungannya dengan masalah di antara anggota tim"],answer:1,explain:"Kadang urutannya: amankan yang mendesak (proyek), lalu tangani konflik saat ada ruang. Keduanya tetap perlu diselesaikan.",hint:"Gencatan senjata + jadwalkan bahas, atau biarkan hancur / abaikan tenggat?"},
{n:48,type:"mcq",micro:"Skenario: kamu ikut andil dalam konflik",q:"Dalam konflik, kamu sadar sikapmu yang ketus ikut memicu. Sikap yang mempercepat penyelesaian:",options:["Bersikeras bahwa kamu hanya bereaksi terhadap lawan dan dialah yang memulai, jadi tak perlu minta maaf","Menyimpan pengakuan itu sendiri dan tidak mengatakannya, karena minta maaf lebih dulu dianggap tanda kalah","Akui: 'Aku juga minta maaf, tadi aku ngomongnya ketus. Itu nggak membantu.' — mengakui andil membuka jalan"],answer:2,explain:"Ketika satu pihak berani mengakui andilnya, pihak lain biasanya lebih mau melakukan hal yang sama.",hint:"Akui andilmu, atau bersikeras 'kamu yang mulai'?"},
{n:49,type:"mcq",micro:"Skenario: konflik & rahasia",q:"Selama menyelesaikan konflik, temanmu bercerita hal pribadi yang menjelaskan sikapnya. Sikap:",options:["Jaga kerahasiaannya; jangan menyebarkannya ke tim atau memakainya melawan dia nanti","Ceritakan ke tim agar mereka ikut mengerti, walau ia bicara secara pribadi","Simpan sebagai 'senjata' bila konflik muncul lagi, supaya kamu punya sesuatu untuk melawan"],answer:0,explain:"Penyelesaian konflik butuh kepercayaan. Membocorkan atau mempersenjatai cerita pribadi menghancurkannya.",hint:"Jaga rahasia, atau sebarkan / jadikan senjata?"},
{n:50,type:"open",micro:"Menyelesaikan konflik beban tidak adil",q:"Kamu merasa selama proyek ini kamu & satu teman mengerjakan jauh lebih banyak daripada dua anggota lain, dan kamu mulai kesal setiap rapat. Konflik belum meledak tapi sudah terasa. Tulis bagaimana kamu akan mengangkat & menyelesaikan masalah ini dengan tim, lalu jelaskan pilihanmu.",explain:"Jawaban baik: angkat masalah sebelum meledak, sampaikan dengan fakta pembagian + perasaan pakai 'aku merasa' (bukan tuduhan 'pemalas'), buka ruang untuk sisi mereka & kemungkinan salah menilai, akui andil sendiri, ajukan solusi konkret (bagi ulang + cek keseimbangan rutin), timbang beban objektif bila ada keberatan, lalu lepaskan kekesalan lama — dengan penjelasan alasan tiap pilihan.",hint:"Angkat sebelum meledak → fakta pembagian + 'aku merasa' (bukan tuduhan) → buka ruang untuk sisi mereka → akui andilmu → solusi konkret (bagi ulang + cek rutin) → lepaskan. Jelaskan alasan tiap langkah.",sample:"(1) Aku tidak menunggu sampai meledak; aku angkat di rapat berikutnya dengan tenang. (2) Aku pakai fakta, bukan tuduhan: 'Aku mau ngomongin pembagian kerja kita. Dari catatan, aku pegang bagian A, B, dan sebagian C; [teman] pegang D dan E; sementara [anggota 3] dan [anggota 4] pegang satu bagian kecil masing-masing. Aku merasa bebannya nggak seimbang dan aku mulai kewalahan.' (3) Aku buka ruang untuk sisi mereka tanpa menyerang: 'Mungkin ada yang aku nggak tahu — apakah bagian kalian ternyata lebih berat dari kelihatannya, atau ada kendala?' Dengarkan. (4) Aku akui bila ada andilku: mungkin di awal aku terlalu cepat mengambil banyak bagian tanpa mengecek keseimbangan bersama. (5) Aku ajukan solusi konkret: 'Untuk sisa proyek, bisa kita bagi ulang? Bagian C yang belum kukerjakan bisa diambil [anggota 3], dan [anggota 4] bantu bagian B. Terus kita cek beban bareng tiap minggu.' (6) Kalau ada yang keberatan, kami timbang bersama perkiraan beban tiap bagian secara objektif. (7) Setelah sepakat, aku lepaskan kekesalan yang lalu dan fokus ke depan. Penjelasan: aku mengangkat masalah SEBELUM meledak karena konflik kecil lebih mudah diselesaikan; aku pakai data pembagian (bukan 'kalian pemalas') supaya tidak memicu pertahanan; aku buka ruang untuk kemungkinan aku salah menilai; aku akui andilku supaya terasa 'kita vs masalah'; dan aku fokus pada solusi + aturan cek keseimbangan supaya tidak terulang."},
{n:51,type:"mcq",micro:"Skenario: konflik soal kredit/pengakuan",q:"Kamu & anggota lain berkonflik karena ia mengklaim ide yang sebenarnya kalian kembangkan bersama. Cara menyelesaikan:",options:["Diam dan menyimpan kesal tanpa menyampaikan kepadanya, berharap ia sadar sendiri dan minta maaf nanti, lalu berharap masalah selesai tanpa pembicaraan","Bicara berdua: 'Waktu kamu bilang itu idemu ke guru, aku merasa tak enak karena kita kembangkan bareng. Aku ingin kontribusi kita diakui.' — spesifik","Menuduh dia pembohong dan pencuri ide di depan seluruh tim, supaya ia dipaksa mengakui kesalahannya segera, walau suasana tim jadi makin tegang"],answer:1,explain:"Konflik soal pengakuan diselesaikan dengan menyebut kejadian spesifik + perasaan + usul (kontribusi berdua diakui), bukan tuduhan atau pendam.",hint:"Spesifik + 'aku merasa' + usul, atau menuduh / pendam?"},
{n:52,type:"mcq",micro:"Skenario: konflik yang kamu picu tanpa sadar",q:"Seorang anggota mendekatimu & bilang sikapmu minggu lalu menyakitinya, padahal kamu merasa biasa saja. Sikap:",options:["'Kamu kebanyakan baper, aku nggak melakukan apa-apa kok.' lalu mengabaikan perasaannya dan melanjutkan pekerjaan seolah tak ada yang terjadi di antara kalian","Membela diri panjang lebar bahwa kamu tidak bersalah dan tidak bermaksud buruk, sampai ia berhenti bicara dan tak berani mengeluh lagi","Dengarkan penuh, jangan langsung membela diri; tanyakan bagian mana yang menyakiti; akui dampaknya & minta maaf atas dampak itu meski kamu tidak bermaksud"],answer:2,explain:"Niatmu & dampak pada orang lain bisa berbeda. Mengakui dampak (tanpa harus mengaku 'jahat') membuka penyelesaian.",hint:"Dengar + akui dampak + minta maaf atas dampak, atau 'baper' / membela diri?"},
{n:53,type:"mcq",micro:"Skenario: konflik karena gaya komunikasi berbeda",q:"Kamu merasa anggota timmu 'kasar' saat memberi masukan; ia merasa dirinya 'cuma jujur & efisien'. Cara menjembatani:",options:["Sepakati bersama: ia berusaha melembutkan sedikit nadanya, kamu berusaha tidak langsung tersinggung oleh gaya langsungnya — keduanya menyesuaikan","Salah satu dari kalian harus mengubah kepribadiannya total supaya cocok dengan yang lain, & yang lebih lama bertahan di tim yang menentukan","Berhenti berkomunikasi langsung dan hanya menyampaikan pesan lewat orang ketiga, supaya tidak ada gesekan di antara kalian, sampai proyek selesai"],answer:0,explain:"Perbedaan gaya komunikasi diselesaikan dengan kedua pihak menyesuaikan sedikit, bukan menuntut satu pihak berubah total.",hint:"Keduanya menyesuaikan sedikit, atau satu berubah total / berhenti bicara?"},
{n:54,type:"mcq",micro:"Skenario: konflik memuncak jadi tangisan",q:"Saat membahas konflik, anggota timmu menangis. Sikap:",options:["Berkata 'jangan nangis, ini bukan hal besar kok' supaya ia cepat tenang dan pembahasan tidak terganggu oleh tangisan yang berkepanjangan","Beri jeda & ruang: 'Nggak apa-apa, kita pelan-pelan. Mau ambil napas dulu?' — jangan menekan untuk terus atau menganggapnya 'drama'","Terus mendesak menyelesaikan pembahasan sekarang selagi semua anggota berkumpul, karena menunda membuat masalah menggantung lagi"],answer:1,explain:"Emosi kuat perlu diberi ruang. Menekan terus atau meremehkan tangisan memperburuk konflik & merusak kepercayaan.",hint:"Beri jeda & ruang, atau mendesak / meremehkan?"},
{n:55,type:"mcq",micro:"Skenario: konflik & anggota yang minta maaf berlebihan",q:"Dalam konflik, seorang anggota langsung minta maaf berlebihan untuk segalanya (bahkan yang bukan salahnya) untuk mengakhiri ketegangan. Sikap yang sehat:",options:["Terima semua permintaan maafnya dan anggap konflik selesai saat itu juga, padahal cara itu hanya membuat masalahnya menumpuk dan makin besar nanti","Menekannya minta maaf lebih banyak lagi atas hal lain, supaya ia sadar seluruh kesalahannya, tanpa mau mendengar pendapat anggota tim yang lain","'Kamu nggak perlu minta maaf buat semuanya. Yang penting kita paham masalahnya & sepakat langkah ke depan.' — jangan biarkan maaf jadi cara menghindar"],answer:2,explain:"Permintaan maaf yang tulus itu baik, tapi 'maaf borongan' untuk mengakhiri ketegangan sering meninggalkan masalah inti tak terbahas.",hint:"Arahkan ke pembahasan nyata, atau terima maaf borongan / tekan lebih?"},
{n:56,type:"mcq",micro:"Skenario: konflik antara kamu & seluruh tim",q:"Kamu berbeda pendapat kuat dengan SELURUH tim & merasa disudutkan. Sikap yang menjaga dirimu & tim:",options:["Sampaikan pandanganmu sekali dengan tenang & alasan; minta didengar tanpa dipotong; lalu terima keputusan tim bila prosesnya adil, kekhawatiranmu dicatat","Menyerah tanpa menyampaikan pendapat dan ikut saja keputusan, karena melawan arus tim hanya membuatmu makin disudutkan, lalu memendam kesal","Menuduh tim mengeroyokmu secara tidak adil lalu keluar dari kelompok, supaya mereka menyadari bahwa mereka telah memperlakukanmu dengan buruk"],answer:0,explain:"Menjadi minoritas terasa berat, tapi menyampaikan sekali dengan jelas lalu menerima keputusan adil lebih baik daripada menyerah diam atau menyerang.",hint:"Sampaikan sekali + minta didengar + terima keputusan adil, atau menyerah / menyerang?"},
{n:57,type:"mcq",micro:"Skenario: konflik & permintaan 'lupakan saja'",q:"Setelah konflik, lawan berkata 'udahlah lupain aja' tapi kamu merasa masalahnya belum benar-benar dibahas. Sikap:",options:["Terus mengungkit-ungkit masalah itu di setiap kesempatan tanpa mengarah ke solusi, sampai lawanmu akhirnya bersedia membahasnya karena merasa terganggu","'Aku mau kita baik lagi juga, tapi aku ingin kita bicarakan sebentar apa yang bikin ini terjadi, biar nggak keulang.' — dorong pembahasan singkat dulu","Ikut 'melupakan' saja padahal dalam hatimu masih mengganjal, supaya suasana tetap baik & kamu tidak dianggap sebagai orang yang suka memperpanjang masalah"],answer:1,explain:"'Lupakan saja' tanpa membahas akar sering membuat konflik yang sama muncul lagi. Bahas singkat dulu, baru lepaskan.",hint:"Dorong pembahasan singkat dulu, atau ikut melupakan / mengungkit terus?"},
{n:58,type:"tf",micro:"Konflik & keputusan sementara",q:"Benar atau Salah: Bila sebuah konflik belum selesai, tim tidak boleh mengambil keputusan apa pun sampai konflik itu benar-benar tuntas, meski tenggat sudah lewat.",answer:false,explain:"Sebaliknya, konflik tidak selalu bisa dituntaskan tepat saat dibutuhkan keputusan. Keputusan sementara yang wajar + menjadwalkan pembahasan konflik lagi nanti lebih baik daripada tim macet total.",hint:"Boleh keputusan sementara + jadwalkan lanjut, atau harus tuntas dulu apa pun?"},
{n:59,type:"open",micro:"Menyusun percakapan menyelesaikan konflik",q:"Anggota timmu, Bram, sudah dua kali menyerahkan bagiannya sangat terlambat tanpa mengabari, dan kamu yang menutupi. Kamu kesal tapi juga tahu Bram mungkin sedang ada masalah. Tulis pembukaan & isi percakapan yang akan kamu lakukan dengan Bram (bukan menyerang, bukan memendam), lalu jelaskan strukturnya.",explain:"Jawaban baik: buka dengan niat positif, sampaikan fakta spesifik (2x terlambat tanpa kabar, dampaknya) + perasaan pakai 'aku merasa', buka ruang & dengar sisi Bram dengan empati, akui andil sendiri bila ada, sepakati langkah konkret ke depan (aturan mengabari + pengingat + bagi beban bila berat), tutup dengan menghargai — lalu jelaskan struktur itu.",hint:"Niat positif → fakta spesifik + 'aku merasa' → dengar sisinya (empati) → akui andilmu → langkah konkret ke depan → tutup menghargai.",sample:"Pembukaan (niat positif): 'Bram, boleh ngobrol bentar berdua? Aku nggak mau ini jadi masalah besar, makanya aku pengin bicara langsung.' Isi (pernyataan 'aku' + spesifik): 'Dua tugas terakhir, bagianmu masuk beberapa hari setelah tenggat dan aku nggak dapat kabar sebelumnya, jadi aku yang buru-buru menyelesaikannya. Aku merasa kewalahan dan sedikit kesal, walau aku yakin kamu nggak sengaja.' Membuka ruang untuk sisinya: 'Ada sesuatu yang lagi kamu hadapi? Aku pengin ngerti dulu situasimu.' (Dengar penuh, tidak memotong, pantulkan: 'Jadi kamu lagi... dan itu bikin susah ngatur waktu, gitu?') Mengakui andil bila ada: 'Mungkin aku juga kurang ngingetin soal tenggat, ya.' Menuju solusi bersama: 'Gimana kalau ke depan kita sepakati: kamu kabari aku minimal sehari sebelum tenggat kalau ada kendala, sekecil apa pun, biar kita bisa atur. Dan aku bakal kirim pengingat 2 hari sebelumnya. Kalau bagianmu memang lagi berat, kita bagi.' Penutup: 'Aku hargai kamu mau dengerin ini. Buatku yang penting kita bisa saling ngandelin.' Struktur: (1) buka dengan niat positif supaya Bram tidak langsung defensif; (2) sampaikan fakta spesifik + perasaan dengan 'aku merasa', bukan 'kamu selalu'; (3) buka ruang & dengar sisinya dengan empati (mungkin ada masalah nyata); (4) akui andilku sendiri supaya terasa 'kita vs masalah'; (5) sepakati langkah konkret ke depan (aturan kabar + pengingat + bagi beban); (6) tutup dengan menghargai & menegaskan hubungan."},
{n:60,type:"open",micro:"Skenario menyeluruh",q:"Kamu ketua tim. Dua anggota, Nadia & Reza, sudah tiga hari saling dingin sejak berdebat soal ide, dan sekarang menolak berkoordinasi sehingga proyek terhambat. Rancang bagaimana kamu membantu mereka menyelesaikan konflik ini (minimal 6 langkah), dan apa yang kamu lakukan bila mereka tetap tidak mau berdamai.",explain:"Jawaban baik: bicara pribadi dengan masing-masing dulu (dengar & pantulkan, tidak memihak), sampaikan dampak ke proyek + niat membantu bukan menghakimi, pertemukan dengan aturan diskusi, cerita bergantian + saling memantulkan sampai diakui, geser ke tujuan bersama + sepakati langkah/aturan ke depan, dorong maaf atas cara bukan pendapat, pantau; bila gagal: tetap profesional (koordinasi lewat perantara) + libatkan pembimbing untuk mediasi + dokumentasi faktual untuk penilaian adil.",hint:"Pribadi dulu (dengar tiap sisi) → sampaikan dampak + niat membantu → pertemukan dengan aturan → cerita + saling memantulkan → tujuan bersama + langkah ke depan → maaf atas cara. Bila gagal: tetap profesional + libatkan pembimbing + dokumentasi.",sample:"(1) Bicara dengan Nadia dan Reza secara PRIBADI dulu, terpisah, dengan nada tidak menghakimi: dengar versi masing-masing secara penuh, pantulkan perasaan mereka, tidak buru-buru memihak — supaya keduanya merasa didengar sebelum dipertemukan. (2) Sampaikan ke masing-masing bahwa proyek terhambat dan tim butuh mereka berkoordinasi, dan bahwa tujuanku membantu menyelesaikan, bukan mencari siapa yang salah. (3) Ajak keduanya duduk bersama di tempat tenang; mulai dengan aturan: bicara bergantian, tidak menghina, tidak mengungkit hal lama, fokus pada masalah & langkah ke depan. (4) Minta tiap orang menceritakan versi & perasaannya secara singkat, yang lain menyimak tanpa memotong; lalu minta tiap orang mengulang inti keluhan lawannya sampai lawan berkata 'ya, itu maksudku' — sering di sini ketahuan sebagian besar adalah salah paham atau ego. (5) Bantu mereka melihat bahwa keduanya sama-sama ingin proyek berhasil; geser fokus ke 'apa yang kita butuhkan supaya bisa kerja sama lagi?'. Sepakati langkah konkret: cara mengambil keputusan bila berbeda pendapat, cara memberi masukan tanpa menyinggung. (6) Bila perlu, dorong mereka saling minta maaf atas CARA (bukan atas pendapat), lalu tegaskan perbedaan ide tidak boleh jadi permusuhan. (7) Pantau apakah koordinasi benar-benar jalan lagi. Bila mereka TETAP tidak mau berdamai: aku sampaikan jujur bahwa untuk sisa proyek mereka tidak harus berteman, tapi harus profesional & berkoordinasi lewat aku sebagai perantara sementara bila perlu; bila sikap dingin mereka melumpuhkan tim, aku libatkan guru/pembimbing untuk menengahi, dan aku dokumentasikan situasi secara faktual supaya penilaian tetap adil."},
{n:61,type:"mcq",micro:"Mengapa tenang dulu penting",q:"Mengapa memberi jeda untuk tenang sebelum membahas konflik hampir selalu membantu?",options:["Karena menunda biasanya menghilangkan masalah dengan sendirinya, sehingga setelah beberapa hari tak ada lagi yang perlu dibicarakan kedua pihak","Tidak ada gunanya; lebih baik membahas langsung saat itu juga, ketika anggota masih ingat persis apa yang dikatakan pihak lain","Saat marah, otak cenderung menyerang & sulit mendengar; setelah tenang, kamu bisa berpikir jernih & memilih kata yang tidak merusak"],answer:2,explain:"Kata-kata yang keluar saat marah sering menambah luka yang butuh waktu lama untuk sembuh. Jeda melindungi hubungan.",hint:"Otak marah menyerang & tak mendengar, atau menunda menghilangkan masalah?"},
{n:62,type:"mcq",micro:"Mengapa dengar dua sisi",q:"Mengapa mendengar kedua sisi cerita penting sebelum menyimpulkan dalam konflik?",options:["Tiap orang mengingat & menceritakan dari sudut pandangnya; satu sisi hampir selalu tidak lengkap & bisa menyesatkan","Karena sopan santun mengharuskan kita mendengar lebih dulu dari pihak yang paling lama kenal dengan kita","Karena pihak yang bicara kedua biasanya lebih benar daripada yang bicara lebih dulu dalam konflik tim"],answer:0,explain:"Banyak 'kesimpulan' konflik yang keliru karena dibuat hanya dari satu versi cerita.",hint:"Satu sisi tidak lengkap, atau sekadar sopan?"},
{n:63,type:"tf",micro:"Konflik vs hubungan",q:"Benar atau Salah: Cara sebuah tim atau pertemanan menangani konflik (bukan apakah mereka pernah berkonflik) adalah salah satu penentu terbesar apakah hubungan itu bertahan & sehat.",answer:true,explain:"Semua hubungan dekat mengalami konflik. Yang bertahan adalah yang bisa membicarakannya dengan jujur & memperbaikinya.",hint:"Cara menangani konflik menentukan, atau apakah pernah berkonflik?"},
{n:64,type:"mcq",micro:"Mengapa 'kamu selalu' memicu pertahanan",q:"Mengapa kalimat 'kamu selalu begitu' membuat konflik makin sulit?",options:["Tidak memicu reaksi karena itu hanya kalimat biasa yang tidak berpengaruh pada cara lawan memahami maksud ucapanmu","Terasa seperti vonis atas karakter (bukan perilaku spesifik), sehingga orang membela diri alih-alih mendengar & memperbaiki","Karena kata 'selalu' terlalu panjang diucapkan sehingga lawan kehilangan fokus, bukan karena maknanya vonis karakter"],answer:1,explain:"'Kamu selalu' & 'kamu tidak pernah' hampir selalu berlebihan & terasa menyerang. Sebut kejadian spesifik.",hint:"Terasa vonis karakter, atau kata terlalu panjang?"},
{n:65,type:"mcq",micro:"Menang argumen vs menyelesaikan konflik",q:"Beda 'memenangkan argumen' & 'menyelesaikan konflik':",options:["Keduanya sama saja, karena sama-sama berakhir dengan keputusan yang diterima oleh sebagian besar anggota tim, dan sama-sama cepat","Menang argumen menyelesaikan konflik, karena pihak yang kalah akan belajar dan hubungan jadi lebih baik, walau awalnya kesal","Menang argumen: satu pihak kalah & sering dendam. Menyelesaikan konflik: masalah teratasi & hubungan terjaga — sering tanpa 'pemenang'"],answer:2,explain:"Kamu bisa 'menang' setiap argumen & tetap kehilangan setiap hubungan. Tujuannya penyelesaian, bukan kemenangan.",hint:"Menang = kalah + dendam vs teratasi + hubungan terjaga, atau sama?"},
{n:66,type:"tf",micro:"Semua konflik harus diselesaikan sekarang?",q:"Benar atau Salah: Setiap konflik, sekecil apa pun, harus langsung dihadapi & dituntaskan saat itu juga, tidak peduli kondisi emosi atau waktu.",answer:false,explain:"Sebaliknya, konflik sepele bisa dibiarkan lewat, dan konflik besar sering lebih baik dibahas setelah semua tenang. Memilih waktu yang tepat adalah bagian dari menyelesaikan konflik dengan baik.",hint:"Selalu tuntaskan seketika, atau pilih waktu & abaikan yang sepele?"},
{n:67,type:"mcq",micro:"Konflik & pertumbuhan",q:"Bagaimana konflik yang diselesaikan baik bisa membuat hubungan lebih kuat?",options:["Kedua pihak belajar lebih banyak tentang kebutuhan & batas satu sama lain, & membuktikan bahwa hubungan bisa bertahan melewati kesulitan","Konflik tidak menguatkan hubungan, karena setiap pertengkaran meninggalkan luka yang tak bisa disembuhkan kedua pihak, sehingga sebaiknya dihindari","Hanya dengan menghindari konflik hubungan bisa menguat, karena orang yang tak bertengkar saling memahami satu sama lain sejak awal"],answer:0,explain:"Setelah melewati konflik dengan jujur & hormat, kepercayaan sering justru bertambah: 'kita bisa membicarakan hal sulit'.",hint:"Belajar kebutuhan & terbukti tahan, atau tak pernah menguatkan?"},
{n:68,type:"mcq",micro:"Menilai apakah perlu penengah",q:"Konflik sebaiknya melibatkan penengah netral ketika...",options:["Hampir tidak perlu, karena meminta bantuan penengah dianggap tanda lemah dan menunjukkan kedua pihak tak mampu menyelesaikan masalahnya","Kedua pihak sudah mencoba berdiskusi tapi selalu buntu, emosi terlalu tinggi untuk bicara produktif, atau ada ketidakseimbangan kekuatan/ketakutan","Untuk semua konflik sejak awal, sekecil apa saja, supaya kedua pihak tidak perlu mencoba bicara dulu dan langsung diputuskan orang lain"],answer:1,explain:"Penengah bukan tanda gagal — kadang pihak luar yang netral bisa membantu melihat yang tidak terlihat dari dalam.",hint:"Saat buntu / emosi tinggi / ada ketakutan, atau selalu / tidak pernah?"},
{n:69,type:"mcq",micro:"Konflik yang tidak sehat dibiarkan",q:"Apa yang terjadi pada tim yang membiarkan konflik tidak sehat berlarut (saling dingin, kubu-kubuan, sindiran)?",options:["Tim jadi lebih fokus bekerja karena tidak membuang waktu membahas hal di luar tugas","Tak ada dampak selama tugas selesai tepat waktu, sebab suasana tim tidak memengaruhi kualitas pekerjaan","Komunikasi macet, kerja terhambat, anggota stres & menarik diri, & sering hasil proyek ikut buruk"],answer:2,explain:"Konflik yang membusuk menguras energi tim & merusak baik hasil maupun hubungan.",hint:"Komunikasi & kerja macet, atau tim lebih fokus?"},
{n:70,type:"order",micro:"Dari konflik yang memanas ke solusi",q:"Urutkan proses membawa konflik yang sudah memanas ke arah penyelesaian.",items:["Hentikan & beri jeda: 'Kita berhenti dulu, lanjut setelah tenang'","Setelah tenang, sepakati untuk fokus pada masalah, bukan saling menyalahkan","Dengar kedua sisi penuh; gali kebutuhan di balik posisi masing-masing","Cari solusi yang memenuhi kebutuhan inti keduanya & sepakati langkah ke depan"],answer:[0,1,2,3],explain:"Jeda → fokus pada masalah → dengar & gali kebutuhan → solusi menang-menang. Bukan lanjut berdebat saat panas.",hint:"Apa langkah pertama saat konflik sedang panas?"},
{n:71,type:"mcq",micro:"Konflik & rasa keadilan",q:"Sebuah solusi konflik lebih mungkin bertahan bila kedua pihak merasa...",options:["Prosesnya adil (semua didengar) & solusinya masuk akal, meski bukan persis yang mereka inginkan di awal","Bahwa mereka menang telak atas lawannya, karena rasa menang membuat orang puas dan mau menjalankan solusi","Bahwa mereka dipaksa menerima solusi oleh pihak yang lebih kuat, sehingga tak ada alasan menentang lagi"],answer:0,explain:"Solusi yang dirasa dipaksakan atau tidak adil sering hanya 'gencatan senjata' yang pecah lagi nanti.",hint:"Proses adil + masuk akal, atau menang telak / dipaksa?"},
{n:72,type:"tf",micro:"Meminta maaf itu kekuatan",q:"Benar atau Salah: Mengakui kesalahan & meminta maaf dengan tulus dalam konflik adalah tanda kekuatan & kedewasaan, bukan kelemahan.",answer:true,explain:"Butuh keberanian & kerendahan hati untuk berkata 'aku salah'. Orang yang tidak pernah bisa minta maaf sulit menyelesaikan konflik apa pun.",hint:"Kekuatan & kedewasaan, atau kelemahan?"},
{n:73,type:"mcq",micro:"Konflik antar kelompok",q:"Konflik antara dua kelompok/kubu dalam organisasi cenderung lebih sulit daripada konflik antar individu karena...",options:["Lebih mudah, karena banyak anggota berarti banyak pilihan dan semua pihak lebih cepat menemukan titik temu","Ada tekanan sosial untuk 'setia pada kubu', identitas kelompok menguat, & lebih banyak orang yang perlu sepakat","Kelompok tidak punya perasaan, jadi konflik antar kelompok hanya soal tugas dan tidak melibatkan emosi anggota"],answer:1,explain:"Konflik kelompok butuh usaha ekstra: forum terbuka, menemukan tujuan bersama yang lebih besar, & sering pihak ketiga.",hint:"Tekanan setia kubu + identitas + lebih banyak orang, atau selalu lebih mudah?"},
{n:74,type:"mcq",micro:"Konflik & asumsi niat buruk",q:"Dalam konflik, mengasumsikan niat buruk pada lawan ('dia sengaja mau menjatuhkanku') cenderung...",options:["Akurat dan berguna, karena prasangka yang cepat biasanya menggambarkan niat lawan dengan benar dan menghemat waktu, sehingga konflik cepat selesai","Membantu menyelesaikan konflik karena kamu bisa langsung menanggapi niat buruk lawan sebelum ia bertindak, sehingga tak perlu menunggu penjelasan","Membuat kamu bereaksi lebih agresif & sulit mendengar; sering asumsi itu keliru — orang bertindak karena alasan yang masuk akal bagi mereka"],answer:2,explain:"Kebanyakan konflik berasal dari kebutuhan/tekanan yang berbeda, bukan kejahatan. Mengasumsikan niat baik (sampai terbukti sebaliknya) membuka jalan.",hint:"Membuat lebih agresif & sering keliru, atau selalu akurat?"},
{n:75,type:"tf",micro:"Konflik bisa dicegah sebagian",q:"Benar atau Salah: Kesepakatan yang jelas di awal tidak berpengaruh pada jumlah konflik tim, karena konflik murni soal kepribadian yang bertabrakan.",answer:false,explain:"Sebaliknya, konflik sering lahir dari ekspektasi yang berbeda & tidak diucapkan. Kesepakatan awal (pembagian tugas, komunikasi, cara keputusan) membuat ekspektasi eksplisit & mencegah banyak konflik.",hint:"Kesepakatan awal mencegah sebagian konflik, atau tak berpengaruh?"},
{n:76,type:"mcq",micro:"Menilai gaya konflikmu sendiri",q:"Kenapa berguna menyadari gaya konflik defaultmu (mis. cenderung menghindar, atau cenderung memaksa)?",options:["Kamu bisa mengenali saat gaya defaultmu kurang cocok untuk situasi & sengaja memilih pendekatan lain","Gaya konflik tidak bisa diubah karena sudah menjadi bawaan kepribadian tiap orang sejak kecil","Tidak ada gunanya mengenali gaya sendiri, karena setiap konflik diselesaikan dengan cara yang sama"],answer:0,explain:"Orang yang cenderung menghindar bisa belajar menghadapi hal penting; yang cenderung memaksa bisa belajar mendengar. Kesadaran adalah langkah pertama.",hint:"Bisa memilih pendekatan lain secara sadar, atau tak bisa diubah?"},
{n:77,type:"mcq",micro:"Konflik & memaafkan",q:"Memaafkan (setelah konflik diselesaikan) berarti...",options:["Menjadi lemah & mudah dimanfaatkan orang lain, karena orang yang memaafkan akan dianggap tidak punya harga diri & akan diperlakukan seenaknya lagi","Melepaskan dendam & tidak terus menghukum lawan atas kesalahan yang sudah dibahas — bukan berarti melupakan pelajaran atau membiarkan hal buruk terulang","Berpura-pura tidak terjadi apa-apa, termasuk melupakan pelajaran dan membiarkan hal buruk yang sama terulang kemudian hari, supaya suasana damai"],answer:1,explain:"Memaafkan membebaskan kamu dari beban dendam. Kamu tetap boleh belajar & menetapkan batas untuk masa depan.",hint:"Lepaskan dendam (tetap belajar & batas), atau lupakan total / jadi lemah?"},
{n:78,type:"mcq",micro:"Konflik yang berulang & aturan",q:"Ketika konflik yang sama terus muncul, solusi yang lebih tahan lama:",options:["Mengulangi permintaan maaf setiap konflik muncul tanpa mengubah cara kerja tim, karena kata maaf sudah memperbaiki hubungan","Menyalahkan orang yang sama tiap konflik muncul, karena dialah penyebab utama masalah yang berulang di tim","Buat kesepakatan/aturan tim yang spesifik mengatasi penyebabnya (mis. 'sebelum mengubah bagian orang, bahas berdua')"],answer:2,explain:"Konflik berulang butuh perubahan sistem/aturan, bukan hanya penyelesaian gejala berulang-ulang.",hint:"Aturan yang mengatasi penyebab, atau maaf berulang / menyalahkan?"},
{n:79,type:"mcq",micro:"Konflik & rasa aman kelompok",q:"Tim yang bisa menyelesaikan konflik dengan sehat memberi anggotanya...",options:["Rasa aman untuk jujur — mereka tahu bahwa menyuarakan masalah tidak akan menghancurkan hubungan atau membuat mereka dimusuhi","Rasa takut untuk bicara, karena menyuarakan masalah hanya memperburuk keadaan dan membuat mereka dimusuhi teman","Tak ada dampak pada suasana tim, sebab cara menangani konflik hanya memengaruhi hasil tugas, bukan perasaan anggota"],answer:0,explain:"Kalau setiap konflik berakhir buruk, anggota belajar untuk diam & menyembunyikan masalah — yang justru lebih berbahaya.",hint:"Rasa aman untuk jujur, atau takut bicara?"},
{n:80,type:"open",micro:"Menganalisis dua cara menangani konflik",q:"Tim A: saat ada konflik, anggota saling menyindir di grup, membentuk kubu, dan tidak pernah membicarakannya langsung — proyek selesai tapi beberapa anggota tidak saling bicara lagi setelahnya. Tim B: saat ada konflik, anggota (dibantu ketua) bicara berdua dengan tenang, mendengar dua sisi, mengakui andil masing-masing, dan menyepakati aturan ke depan. Jelaskan mengapa cara Tim B lebih baik untuk hasil & hubungan (minimal 4 alasan), dan 1 hal yang membuat cara Tim B lebih sulit dilakukan.",explain:"Jawaban baik memberi minimal 4 alasan Tim B lebih baik (masalah inti selesai / tidak berulang, hubungan terjaga, komunikasi & kerja lancar, anggota belajar keterampilan + tim lebih tahan, aturan mencegah pengulangan) dan 1 hal yang membuatnya lebih sulit (butuh keberanian menghadapi ketidaknyamanan + menahan emosi/ego + waktu & niat semua pihak; menyindir/menghindar terasa lebih mudah jangka pendek).",hint:"Alasan B: masalah selesai, hubungan terjaga, komunikasi lancar, belajar keterampilan, aturan cegah ulang. Kesulitan: butuh keberanian + menahan ego + waktu; menghindar terasa lebih mudah.",sample:"Cara Tim B lebih baik karena: (1) Masalah inti benar-benar diselesaikan, bukan hanya ditekan — jadi konflik yang sama tidak terus muncul, sementara di Tim A akar masalah tetap ada. (2) Hubungan antar anggota terjaga: di Tim B mereka tetap bisa bekerja sama dan berteman setelahnya, sedangkan di Tim A beberapa tidak saling bicara lagi — kerugian yang bertahan lama. (3) Komunikasi tim tetap lancar selama proyek karena tidak ada sindiran dan kubu yang menghambat koordinasi; di Tim A, konflik yang membusuk kemungkinan membuat kerja lebih berat. (4) Anggota Tim B belajar keterampilan menyelesaikan konflik yang berguna seumur hidup, dan tim jadi lebih tahan menghadapi konflik berikutnya. (5) Dengan mengakui andil masing-masing dan menyepakati aturan, Tim B mengurangi peluang konflik serupa terulang. Yang membuat cara Tim B lebih sulit: butuh keberanian menghadapi ketidaknyamanan bicara langsung, kemampuan menahan emosi dan ego (mengakui andil sendiri, mendengar tanpa membela diri), dan waktu serta niat dari semua pihak untuk duduk membahasnya — sedangkan menyindir dan menghindar terasa lebih mudah dan aman dalam jangka pendek."},
{n:81,type:"mcq",micro:"Kasus: konflik dengan anggota yang mengintimidasi",q:"Seorang anggota menyelesaikan konflik dengan cara mengintimidasi (membentak, mengancam mengucilkan). Sikap:",options:["Balas mengintimidasi dia lebih keras, supaya ia takut dan tak berani mengulangi perbuatannya terhadapmu maupun anggota lain","Jangan hadapi sendirian bila merasa tidak aman; libatkan guru/pembimbing; konflik tidak boleh diselesaikan lewat rasa takut","Mengalah dan menuruti keinginannya agar dia tidak marah, serta tidak melaporkannya karena takut keadaan makin buruk"],answer:1,explain:"Ada batas: menyelesaikan konflik butuh rasa aman. Bila ada intimidasi, melibatkan orang dewasa tepercaya adalah langkah yang benar.",hint:"Libatkan pembimbing bila tidak aman, atau selalu mengalah / balas mengancam?"},
{n:82,type:"mcq",micro:"Kasus: konflik & kamu di posisi lemah",q:"Kamu berkonflik dengan seseorang yang lebih senior/berkuasa & takut menyampaikan keluhanmu. Sikap:",options:["Diam dan menanggung sendiri tanpa bercerita, karena orang yang berkuasa tidak mau mendengarkan keluhan dari bawahannya, jadi lebih baik menunggu dia berubah","Menyerang balik secara terbuka di depan banyak orang supaya ia malu & menyadari kesalahannya, serta tidak berani memperlakukanmu seenaknya lagi nanti","Sampaikan dengan hormat & pernyataan 'aku', pilih waktu yang tepat, fokus pada masalah spesifik; bila terlalu berisiko, minta bantuan pihak ketiga tepercaya"],answer:2,explain:"Ketidakseimbangan kekuatan membuat konflik sulit; menyampaikan dengan hormat + fokus spesifik + bantuan pihak ketiga bila perlu adalah jalan yang wajar.",hint:"Hormat + spesifik + bantuan bila perlu, atau diam / menyerang?"},
{n:83,type:"tf",micro:"Refleksi: konflik adalah bagian normal kerja sama",q:"Benar atau Salah: Belajar menyelesaikan konflik dengan sehat adalah bagian tak terpisahkan dari belajar bekerja sama — bukan sesuatu yang hanya dibutuhkan oleh tim yang 'bermasalah'.",answer:true,explain:"Setiap tim yang bekerja cukup lama & serius akan mengalami konflik. Keterampilannya adalah aset, bukan tanda kegagalan.",hint:"Bagian normal kerja sama, atau hanya untuk tim bermasalah?"},
{n:84,type:"mcq",micro:"Kasus: konflik lama yang tak pernah selesai",q:"Kamu & seorang teman punya konflik lama yang tidak pernah dibicarakan & masih terasa canggung. Sikap yang membangun:",options:["Ajak bicara: 'Aku ngerasa ada yang ganjel di antara kita sejak dulu. Aku pengin kita selesaikan, boleh ngobrol?' — membuka pintu dengan tenang","Biarkan kecanggungan itu berlangsung terus, karena membuka masalah lama hanya menimbulkan pertengkaran baru yang lebih besar, jadi lebih aman diam","Bersikap seolah semuanya baik padahal ada yang mengganjal, supaya tak ada yang canggung dan hubungan tetap hangat, walau tidak jujur"],answer:0,explain:"Konflik lama yang dipendam menyandera hubungan. Membukanya dengan lembut sering melegakan kedua pihak.",hint:"Buka pembicaraan dengan tenang, atau biarkan canggung / pura-pura baik?"},
{n:85,type:"order",micro:"Memfasilitasi rekonsiliasi tim yang terbelah",q:"Urutkan langkah membantu tim yang sudah terbelah dua kubu untuk berbaikan & lanjut bekerja.",items:["Akui terbuka bahwa ada perpecahan & itu menghambat tim","Sepakati aturan pertemuan: bicara hormat, tidak mengungkit hal lama, fokus ke depan","Beri tiap kubu ruang menyampaikan keprihatinan & kebutuhannya; kubu lain memantulkan","Temukan tujuan bersama yang lebih besar & sepakati langkah + aturan kerja sama ke depan"],answer:[0,1,2,3],explain:"Akui masalah → aturan aman → dengar & pantulkan tiap kubu → tujuan bersama & langkah ke depan. Rekonsiliasi butuh proses yang sengaja.",hint:"Apa yang diakui terbuka sebelum menetapkan aturan pertemuan?"},
{n:86,type:"mcq",micro:"Kasus: kamu penengah tapi punya pendapat sendiri",q:"Kamu menengahi konflik dua teman, tapi kamu diam-diam setuju dengan salah satu. Sikap yang menjaga netralitasmu sebagai penengah:",options:["Batalkan peran penengah dan biarkan mereka menyelesaikannya sendiri, karena kamu sudah tidak bisa adil terhadap keduanya sejak awal, lalu serahkan keputusan kepada guru","Tahan pendapat pribadimu selama menengahi; fokus membantu keduanya saling mendengar & menemukan solusi sendiri; sampaikan pendapatmu (bila relevan) hanya setelah keduanya sudah tenang & sebagai satu masukan","Langsung dukung pihak yang kamu setujui dan bantu dia meyakinkan lawannya, supaya konflik cepat selesai dan keputusan akhir berpihak pada yang benar, dan hal itu tidak perlu dibahas dengan anggota yang lain"],answer:1,explain:"Penengah yang terlihat memihak kehilangan kepercayaan kedua pihak. Netralitas selama proses lebih membantu.",hint:"Tahan pendapat selama menengahi, atau langsung memihak / mundur?"},
{n:87,type:"tf",micro:"Menyelesaikan konflik bukan berarti selalu berdamai sempurna",q:"Benar atau Salah: Kadang hasil terbaik dari menyelesaikan konflik bukanlah dua orang menjadi sahabat lagi, melainkan mereka bisa saling menghormati & bekerja sama secara profesional meski tidak dekat.",answer:true,explain:"Tidak semua konflik berakhir dengan pelukan. 'Bisa bekerja sama dengan hormat' adalah hasil yang sah & sering cukup.",hint:"Harus jadi sahabat lagi, atau cukup bisa bekerja sama dengan hormat?"},
{n:88,type:"mcq",micro:"Kasus: konflik karena nilai/prinsip yang berbeda",q:"Konflik timmu berakar pada perbedaan nilai (mis. satu pihak menganggap 'yang penting menang', satu 'yang penting jujur'). Sikap:",options:["Perdebatkan sampai satu pihak mengalah soal nilainya, karena tim hanya bisa bekerja bila semua anggota memegang keyakinan yang sama tentang cara bermain jujur atau curang, lalu hasil akhirnya dicatat sebagai keputusan tim","Bubarkan tim dan bentuk dua tim baru berdasarkan keyakinan masing-masing, supaya tiap tim bisa berlomba sesuai nilai yang dipegangnya tanpa berkompromi, lalu keduanya mendaftar sendiri-sendiri ke panitia lomba","Akui bahwa ini perbedaan nilai yang dalam; fokus pada apa yang bisa disepakati untuk proyek ini (mis. 'kita menang dengan cara yang jujur'); hormati bahwa perbedaan nilai itu ada tanpa memaksa satu pihak berubah keyakinan"],answer:2,explain:"Perbedaan nilai jarang diselesaikan lewat debat. Yang bisa dilakukan: temukan kesepakatan praktis untuk konteks ini + saling menghormati.",hint:"Kesepakatan praktis + saling hormat, atau debat sampai mengalah / bubar?"},
{n:89,type:"mcq",micro:"Kasus: setelah konflik, satu pihak masih menyimpan dendam",q:"Konflik sudah 'diselesaikan' tapi satu anggota masih dingin & menyimpan dendam. Sikap tim:",options:["Beri waktu; sampaikan dengan tenang bahwa kamu menghargai dia & ingin hubungan membaik; jangan memaksa 'move on' tapi juga jangan biarkan sikap dinginnya melumpuhkan tim tanpa dibicarakan","Balas mendinginkan dia dan mengabaikannya, supaya ia menyadari sikap dinginnya tidak menyenangkan bagi anggota tim lain, sehingga suasana tim berubah, lalu menunggu ia mendekat","Terus memaksa dia setiap hari dengan pertanyaan 'sudah damai kan?' sampai ia mau mengaku dan bersikap seperti biasa terhadap anggota tim, walau ia belum siap berbicara"],answer:0,explain:"Memaafkan butuh waktu berbeda-beda. Beri ruang + tunjukkan itikad baik, tapi tetap bicarakan bila sikapnya menghambat kerja tim.",hint:"Beri waktu + tunjukkan itikad + bicarakan bila menghambat, atau balas dingin / memaksa?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ketua tim OSIS 10 orang. Setelah acara besar yang melelahkan, tim terpecah: sebagian menyalahkan sebagian lain atas kekacauan di hari-H, ada yang tersinggung merasa kerja kerasnya tidak diakui, dan suasana rapat berikutnya penuh sindiran. Rancang bagaimana kamu memimpin tim keluar dari konflik ini secara menyeluruh. Minimal 6 langkah dengan alasan.",explain:"Jawaban baik: bicara pribadi dengan yang terluka dulu, buka rapat dengan mengakui masalah + niat membereskan bukan mencari kambing hitam, tetapkan aturan diskusi, lakukan refleksi terstruktur yang fokus pada sistem/proses bukan menyalahkan orang, akui secara spesifik kontribusi yang merasa tidak dihargai + jadikan kebiasaan, tangani konflik personal tajam lewat mediasi terpisah, tutup dengan aturan/perbaikan konkret + penegasan 'satu tim, bawa pelajaran bukan dendam', dan follow up.",hint:"Pribadi dulu dengan yang terluka → buka rapat akui masalah + niat → aturan diskusi → refleksi fokus proses bukan orang → akui kontribusi yang merasa diabaikan → mediasi personal terpisah → aturan perbaikan + 'satu tim' → follow up.",sample:"(1) Sebelum rapat, aku bicara singkat dengan beberapa anggota yang tampak paling terluka/marah secara pribadi, untuk mendengar keprihatinan mereka dan menunjukkan bahwa aku peduli — supaya mereka datang ke rapat merasa sudah sedikit didengar. (2) Buka rapat dengan mengakui terus terang: 'Acara kemarin melelahkan dan ada yang tidak berjalan lancar. Aku lihat kita jadi saling menyalahkan dan tersindir. Rapat ini aku ingin kita pakai untuk membereskannya, bukan mencari kambing hitam.' Alasan: menamai masalah terbuka menghentikan sindiran terpendam. (3) Tetapkan aturan: bicara bergantian, pakai 'aku merasa', fokus pada apa yang bisa dipelajari, tidak menyerang pribadi. (4) Lakukan refleksi terstruktur, bukan saling tuduh: minta tiap orang menyebut satu hal yang menurutnya berjalan baik dan satu hal yang bisa diperbaiki dari SISTEM/PROSES kita (bukan dari orang tertentu) — mis. 'briefing panitia kurang jelas', 'tidak ada rencana cadangan'. Ini menggeser dari 'siapa salah' ke 'apa yang kita perbaiki'. (5) Khusus untuk yang merasa kerja kerasnya tidak diakui: akui kontribusi mereka secara spesifik dan terbuka di rapat, dan jadikan 'mengakui kontribusi tiap orang' sebagai bagian dari evaluasi rutin ke depan. (6) Bila ada konflik personal yang tajam antara dua-tiga orang, aku tangani terpisah setelah rapat dengan proses mediasi (dengar dua sisi, saling memantulkan, sepakati cara kerja ke depan). (7) Akhiri rapat dengan menyusun beberapa aturan/perbaikan konkret untuk acara berikutnya berdasarkan refleksi tadi, dan tegaskan: 'Kita satu tim. Acara kemarin sudah lewat; yang kita bawa adalah pelajarannya, bukan dendamnya.' (8) Setelah itu aku pantau suasana; kalau masih ada yang dingin, aku follow up pribadi."},
{n:91,type:"mcq",micro:"Kasus: konflik & media sosial",q:"Konflik timmu 'bocor' ke media sosial (seseorang memposting sindiran). Sikap:",options:["Screenshot sindiran itu lalu sebarkan ke lebih banyak orang supaya tahu siapa yang memulai dan ia ditekan banyak teman sekaligus","Jangan menanggapi di publik; tangani konflik lewat pembicaraan langsung; sepakati bahwa urusan tim diselesaikan di dalam, bukan diumbar","Balas dengan postingan sindiran di akunmu sendiri, supaya pandanganmu juga terlihat dan tak hanya satu sisi yang didengar"],answer:1,explain:"Konflik yang dibawa ke publik makin sulit diselesaikan & merugikan semua. Kembalikan ke jalur pribadi.",hint:"Tangani langsung + jangan tanggapi publik, atau balas sindiran / sebarkan?"},
{n:92,type:"tf",micro:"Refleksi: menang argumen bisa berarti kalah hubungan",q:"Benar atau Salah: Kamu bisa 'memenangkan' setiap perdebatan dalam konflik dengan menekan lawan, tetapi tetap merugi karena hubungan & kepercayaan rusak — sehingga menyelesaikan konflik bukan tentang menang.",answer:true,explain:"Tujuan menyelesaikan konflik adalah masalah teratasi + hubungan terjaga, bukan skor kemenangan.",hint:"Menang argumen bisa merusak hubungan, atau selalu menguntungkan?"},
{n:93,type:"mcq",micro:"Kasus: kamu diminta memihak dalam konflik dua teman",q:"Dua sahabatmu berkonflik & masing-masing ingin kamu 'di pihaknya'. Sikap:",options:["Pilih salah satu dan ikut memusuhi yang lain, supaya hubunganmu dengan sahabat pilihanmu makin dekat dan tidak ada tekanan","Ceritakan rahasia yang satu kepada yang lain untuk membantu mereka saling memahami, walau rahasia itu dititipkan secara pribadi","'Aku sayang kalian berdua & nggak mau milih. Aku bisa bantu kalian bicara, tapi aku nggak akan jadi senjata di antara kalian.'"],answer:2,explain:"Menolak dijadikan alat dalam konflik orang lain, sambil menawarkan bantuan netral, menjaga kedua pertemanan & tidak memperburuk konflik.",hint:"Tolak memihak + tawarkan bantuan netral, atau pilih pihak / bocorkan rahasia?"},
{n:94,type:"mcq",micro:"Kasus: konflik terselesaikan tapi pelajaran hilang",q:"Konflik selesai dengan baik, tapi tim langsung lanjut tanpa membahas apa yang bisa dicegah. Risikonya:",options:["Konflik serupa bisa terulang karena penyebab/pola tidak dibahas & tidak dibuat aturan pencegahan","Tak ada risiko; yang penting konflik sudah damai dan semua sudah saling memaafkan","Membahas pelajaran dari konflik justru memicu konflik lagi, jadi lebih baik dibiarkan dan tak dibicarakan lagi"],answer:0,explain:"Refleksi singkat setelah konflik ('apa yang memicu ini? bagaimana mencegahnya?') mengubah konflik jadi perbaikan sistem tim.",hint:"Bisa terulang tanpa refleksi, atau tak ada risiko?"},
{n:95,type:"tf",micro:"Konflik & kepemimpinan",q:"Benar atau Salah: Seorang pemimpin tim sebaiknya tidak pernah ikut campur dalam konflik antar anggota; membiarkan mereka menyelesaikannya sendiri selalu pilihan terbaik apa pun situasinya.",answer:false,explain:"Sebaliknya, salah satu tugas terpenting pemimpin adalah menangani konflik lebih awal & memfasilitasi penyelesaiannya. Membiarkannya membusuk membiarkan racun menyebar ke seluruh tim.",hint:"Tugas pemimpin menangani konflik, atau selalu membiarkan?"},
{n:96,type:"mcq",micro:"Kasus: refleksi soal caramu menghadapi konflik",q:"Cara melatih keterampilan menyelesaikan konflik lewat refleksi:",options:["Mengabaikan evaluasi caramu menghadapi konflik setelah masalah selesai, karena yang penting konfliknya sudah berakhir dan hubungan kembali baik seperti sebelumnya","Setelah konflik: apakah aku tenang dulu? apakah aku mendengar sisi lain? apakah aku menyerang orang atau masalah? apakah aku mengakui andilku? apa satu hal yang akan kuperbaiki?","Menyimpulkan bahwa lawan yang bersalah dalam setiap konflik, sehingga kamu tidak merasa perlu mengubah sikap atau kebiasaanmu sedikit pun, lalu melanjutkan kerja"],answer:1,explain:"Meninjau caramu sendiri (bukan hanya menilai lawan) mempercepat kamu jadi lebih baik dalam menghadapi konflik berikutnya.",hint:"Evaluasi caramu sendiri, atau menyalahkan lawan / tak pernah?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti menyelesaikan konflik:",options:["Diam dan mengalah dalam setiap perselisihan agar tidak ada keributan, serta menghindari pembahasan konflik karena hanya menambah masalah baru, walaupun kerja sama jadi makin sulit dan masalahnya menumpuk","Menangkan setiap argumen dengan menekan lawan sampai menyerah, karena tim lebih tertib bila anggotanya mengikuti pendapat paling kuat, walaupun perasaan anggota lain jarang didengar dan masalahnya menumpuk","Konflik wajar & bisa menguatkan bila ditangani baik; tenang dulu, bicara berdua, dengar dua sisi, pakai 'aku merasa', fokus pada masalah bukan orang, cari solusi menang-menang, akui andilmu — libatkan penengah bila buntu"],answer:2,explain:"Ringkasan: wajar + tenang dulu + langsung & berdua + dua sisi + 'aku merasa' + masalah bukan orang + kebutuhan + menang-menang + akui andil + lepaskan + penengah bila perlu.",hint:"Wajar, tenang dulu, langsung, dua sisi, 'aku merasa', masalah bukan orang, kebutuhan, menang-menang, akui andil, lepaskan — rangkai."},
{n:98,type:"tf",micro:"Refleksi: menyelesaikan konflik melayani hasil & hubungan",q:"Benar atau Salah: Menyelesaikan konflik dengan baik bertujuan mencapai dua hal sekaligus: masalah yang menyebabkan konflik benar-benar teratasi, DAN hubungan antar orang yang terlibat tetap (atau menjadi lebih) sehat.",answer:true,explain:"Kalau masalah teratasi tapi hubungan hancur, atau hubungan 'damai' tapi masalah dibiarkan — keduanya belum berhasil.",hint:"Masalah teratasi + hubungan sehat, atau salah satu?"},
{n:99,type:"mcq",micro:"Kasus: memulai jadi lebih baik menghadapi konflik",q:"Cara termudah mulai memperbaiki caramu menghadapi konflik:",options:["Di konflik kecil berikutnya, latih satu hal: beri jeda sebelum merespons, ATAU pakai satu kalimat 'aku merasa...' alih-alih 'kamu selalu...', ATAU tanyakan sisi lawan dulu","Menunggu sampai ada konflik besar yang serius untuk mulai 'berlatih', karena konflik kecil tidak cukup penting untuk dijadikan kesempatan belajar menyelesaikan masalah","Menghindari konflik dengan cara tidak berpendapat berbeda dan setuju saja dengan teman, sehingga kamu tak perlu belajar menanganinya, sampai lulus nanti"],answer:0,explain:"Keterampilan menghadapi konflik tumbuh dari latihan di konflik-konflik kecil sehari-hari.",hint:"Latih satu hal di konflik kecil, atau menunggu yang besar / menghindar?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi menyelesaikan konflik",q:"Tulis 'aturan pribadi menyelesaikan konflik' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: jeda untuk tenang, bicara langsung & berdua (bukan sindiran/gosip), pernyataan 'aku' spesifik, dengar & pantulkan sisi lawan, akui andil sendiri, fokus masalah + gali kebutuhan + cari menang-menang, lepaskan setelah selesai (tanpa dendam, tetap ambil pelajaran), libatkan penengah bila buntu atau tidak aman.",hint:"Ambil satu pelajaran tiap fase — jeda tenang, bicara langsung, 'aku merasa', dengar & pantulkan, akui andil, masalah + kebutuhan + menang-menang, lepaskan, penengah bila perlu — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Saat konflik memanas, aku memberi jeda untuk tenang sebelum membahas — karena kata-kata yang keluar saat marah sulit ditarik & sering menambah luka. (2) Aku membicarakan konflik langsung dengan orang yang bersangkutan, berdua & di tempat tenang — bukan lewat sindiran, mendiamkan, atau menyebarkan cerita satu sisi ke orang lain. (3) Aku memakai pernyataan 'aku merasa... waktu...' yang spesifik, bukan 'kamu selalu...' yang menyerang karakter — supaya lawan mendengar, bukan membela diri. (4) Aku mendengar sisi lawan sampai selesai & mengulang intinya untuk memastikan aku paham — karena banyak konflik sebenarnya salah paham. (5) Aku mengakui bagian yang jadi andilku — karena konflik jarang murni salah satu pihak, & mengakui andil membuka jalan. (6) Aku fokus pada masalah yang perlu dipecahkan & kebutuhan di balik posisi kami, mencari solusi yang memenuhi kebutuhan inti kedua pihak — bukan berusaha 'menang'. (7) Setelah konflik selesai, aku melepaskannya: tidak mengungkit-ungkit & tidak menyimpan dendam, sambil tetap membawa pelajarannya. (8) Bila kami sudah mencoba tapi buntu, atau bila aku merasa tidak aman, aku melibatkan penengah/orang dewasa tepercaya."},
];
